F.e('e1110',r'q=ms\Delta t\qquad(11.10)','q = m s Δt   (11.10)')
F.p('a2')
F.e('e1111',r'q=C\Delta t\qquad(11.11)','q = C Δt   (11.11)')
F.p('h3','b1','h4','c1','h5','c2','d0','d1','d2','d3','d4','d5')
F.done()
